using Asp.Versioning;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Servicio.RetazoMarket.Api.Extensions;using Servicio.RetazoMarket.Api.Models.Common;using Servicio.RetazoMarket.Business.DTOs.ProductoMaterial;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;
namespace Servicio.RetazoMarket.Api.Controllers.V1.Internal.Catalogo;
[ApiController][ApiVersion("1.0")][Authorize(Policy=AuthorizationExtensions.AdministradorPolicy)][Route("api/v{version:apiVersion}/internal/productos-materiales")][ProducesResponseType(typeof(ApiErrorResponse),400)][ProducesResponseType(typeof(ApiErrorResponse),401)][ProducesResponseType(typeof(ApiErrorResponse),403)][ProducesResponseType(typeof(ApiErrorResponse),404)]
public class ProductosMaterialesController:ControllerBase{private readonly IProductoMaterialService _s;public ProductosMaterialesController(IProductoMaterialService s)=>_s=s;
[HttpGet("producto/{idProducto:int}/material/{idMaterial:int}")]public async Task<IActionResult> Obtener(int idProducto,int idMaterial,CancellationToken ct)=>Ok(ApiResponse<ProductoMaterialResponse>.Ok(await _s.ObtenerAsync(idProducto,idMaterial,ct)??throw new NotFoundException("La receta no existe.")));
[HttpGet("producto/{id:int}")]public async Task<IActionResult> PorProducto(int id,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<ProductoMaterialResponse>>.Ok(await _s.ObtenerPorProductoAsync(id,ct)));
[HttpPost]public async Task<IActionResult> Crear([FromBody]CrearProductoMaterialRequest r,CancellationToken ct){var x=await _s.CrearAsync(r,ct);return CreatedAtAction(nameof(Obtener),new{version="1.0",idProducto=x.id_producto,idMaterial=x.id_material},ApiResponse<ProductoMaterialResponse>.Ok(x,"Material agregado a la receta."));}
[HttpPut("producto/{idProducto:int}/material/{idMaterial:int}")]public async Task<IActionResult> Actualizar(int idProducto,int idMaterial,[FromBody]ActualizarProductoMaterialRequest r,CancellationToken ct){r.id_producto=idProducto;r.id_material=idMaterial;return Ok(ApiResponse<ProductoMaterialResponse>.Ok(await _s.ActualizarAsync(r,ct)??throw new NotFoundException("La receta no existe.")));}}
